	('2101359f-f27e-4ef0-b021-f4ea7a822d43', 'page', 1785814681231, 'services', '/services', 'Our services', '<p>Clarity calls, individual, couple, workplace, premarital, infidelity recovery, teen and family counselling.</p>', NULL, 'publish', '2026-08-22 02:44:45.958+00', '2026-08-04 03:38:01.231+00', NULL, NULL, '{"sections": [{"id": "services-hero", "body": "Every Talk Space service is delivered by a licensed Nigerian therapist. Choose the format that fits, or ask us and we will recommend one after a short conversation.", "type": "hero", "align": "center", "image": {"alt": "", "src": ""}, "links": [{"id": "services-hero-book", "href": "/book", "label": "Book a session", "variant": "primary"}, {"id": "services-hero-price", "href": "/pricing", "label": "See pricing", "variant": "outline"}], "width": "wide", "hidden": false, "eyebrow": "Our services", "heading": "Care shaped around the", "spacing": "lg", "surface": "cream", "headingAfter": "in front of us.", "headingEmphasis": "person"}, {"id": "services-gallery", "type": "gallery", "align": "left", "width": "full", "hidden": false, "images": [{"id": "gal-svc-clarity", "alt": "African care team discussing a counselling intake plan", "src": "asset:african-team", "caption": "Clarity Call"}, {"id": "gal-svc-individual", "alt": "A Nigerian therapist and client in a warm one-to-one counselling session", "src": "asset:individual-therapy", "caption": "Individual Therapy"}, {"id": "gal-svc-couple", "alt": "A young African couple holding hands during a couples therapy session", "src": "asset:couples-therapy", "caption": "Couple Therapy"}, {"id": "gal-svc-organizational", "alt": "African professionals in a calm workplace counselling conversation", "src": "asset:african-team", "caption": "Organizational Counselling"}, {"id": "gal-svc-premarital", "alt": "An African couple in a calm counselling conversation", "src": "asset:ts-marriage-couple", "caption": "Premarital Counselling"}, {"id": "gal-svc-infidelity", "alt": "An African couple in a serious counselling conversation", "src": "asset:african-couch", "caption": "Infidelity Recovery Therapy"}, {"id": "gal-svc-teen", "alt": "An African family seated together in a warm home setting", "src": "asset:family-therapy", "caption": "Teen/Child Therapy"}, {"id": "gal-svc-family", "alt": "A small group of African adults in a circle in a family therapy session", "src": "asset:group-therapy", "caption": "Family Therapy"}], "heading": "", "spacing": "sm", "surface": "cream", "speedSeconds": 50}, {"id": "services-list", "body": "", "type": "featureList", "align": "left", "cards": [{"id": "svc-clarity", "body": "A short paid consultation for clients who want help choosing the right service, understanding next steps, or asking a focused question before booking therapy.", "href": "/book", "tone": "default", "image": {"alt": "African care team discussing a counselling intake plan", "src": "asset:african-team"}, "title": "Clarity Call", "bullets": ["15-minute online or phone consultation", "Best for fit, direction and next-step guidance", "Not a full therapy session or emergency support"], "tagline": "A focused 15-minute first step.", "linkLabel": "Book a clarity call"}, {"id": "svc-individual", "body": "For anxiety, depression, burnout, grief, self-esteem, identity and life transitions. Weekly or fortnightly 50-minute sessions with the same therapist throughout.", "href": "/book", "tone": "dark", "image": {"alt": "A Nigerian therapist and client in a warm one-to-one counselling session", "src": "asset:individual-therapy"}, "title": "Individual Therapy", "bullets": ["CBT, ACT, psychodynamic and integrative approaches", "Online video or in-person at our Lagos rooms", "Free 15-minute intro call available on request"], "tagline": "One-to-one support, at your pace.", "linkLabel": "Book individual therapy"}, {"id": "svc-couple", "body": "For couples navigating conflict, communication, intimacy, parenting differences, trust issues, or the pressure of repeated unresolved arguments.", "href": "/book", "tone": "default", "image": {"alt": "A young African couple holding hands during a couples therapy session", "src": "asset:couples-therapy"}, "title": "Couple Therapy", "bullets": ["Emotion-focused and Gottman-informed approaches", "75-minute sessions with a relational therapist", "Individual check-ins available alongside joint sessions"], "tagline": "For the relationship you want to keep growing.", "linkLabel": "Book couple therapy"}, {"id": "svc-organizational", "body": "For organisations that want confidential employee support, workplace wellness sessions, leadership coaching, and practical care for burnout, stress and team conflict.", "href": "/contact", "tone": "default", "image": {"alt": "African professionals in a calm workplace counselling conversation", "src": "asset:african-team"}, "title": "Organizational Counselling", "bullets": ["EAP-style individual support for staff", "Team wellness sessions and psychoeducation", "Workplace conflict, burnout and leadership support"], "tagline": "Mental health support for healthier teams.", "linkLabel": "Talk to our team"}, {"id": "svc-premarital", "body": "Structured sessions for engaged or seriously committed partners who want to explore expectations, communication, family systems, faith, finances and shared values before marriage.", "href": "/book", "tone": "default", "image": {"alt": "An African couple in a calm counselling conversation", "src": "asset:ts-marriage-couple"}, "title": "Premarital Counselling", "bullets": ["Communication, conflict and expectation mapping", "Values, finances, family boundaries and intimacy", "Personal and couple profiling where appropriate"], "tagline": "Prepare for marriage with clarity and care.", "linkLabel": "Book premarital counselling"}, {"id": "svc-infidelity", "body": "Compassionate therapy for individuals or couples processing betrayal, disclosure, grief, anger, repair, boundaries, and decisions about whether and how to rebuild trust.", "href": "/book", "tone": "default", "image": {"alt": "An African couple in a serious counselling conversation", "src": "asset:african-couch"}, "title": "Infidelity Recovery Therapy", "bullets": ["Stabilise emotions and reduce repeated conflict", "Process betrayal, disclosure and repair conversations", "Rebuild trust or make clear decisions with support"], "tagline": "Structured support after betrayal.", "linkLabel": "Book infidelity recovery"}, {"id": "svc-teen", "body": "Support for children and adolescents experiencing behavioural concerns, anxiety, school-related stress, emotional regulation challenges or family transitions.", "href": "/book", "tone": "dark", "image": {"alt": "An African family seated together in a warm home setting", "src": "asset:family-therapy"}, "title": "Teen/Child Therapy", "bullets": ["Behavioural, play-informed and art-informed therapy", "Parent guidance and family collaboration", "Age-appropriate care from specialist clinicians"], "tagline": "Specialist care for younger clients.", "linkLabel": "Book teen or child therapy"}, {"id": "svc-family", "body": "For families navigating conflict, sibling rivalry, blended households, elder care tension, parenting differences or major life transitions.", "href": "/book", "tone": "default", "image": {"alt": "A small group of African adults in a circle in a family therapy session", "src": "asset:group-therapy"}, "title": "Family Therapy", "bullets": ["Systemic and structural family therapy", "Support for intergenerational relationships", "Sessions include the members most affected"], "tagline": "Bring the whole system into the room.", "linkLabel": "Book family therapy"}], "width": "wide", "hidden": false, "eyebrow": "", "heading": "", "spacing": "lg", "surface": "page"}, {"id": "services-cta", "body": "Book a clarity call and we will recommend the right starting point.", "type": "cta", "align": "center", "links": [{"id": "services-cta-book", "href": "/book", "label": "Book a session", "variant": "primary"}, {"id": "services-cta-contact", "href": "/contact", "label": "Talk to us first", "variant": "outline"}], "width": "content", "hidden": false, "eyebrow": "", "heading": "Not sure which service fits?", "spacing": "lg", "surface": "cream"}]}', '2026-08-04 03:38:01.231+00', '2026-08-22 02:44:46.049994+00', NULL, NULL, NULL, NULL),
