	('c67aa275-f65b-49b3-aa19-bb3e164da620', 'page', 1785815591914, 'pricing', '/pricing', 'Pricing', '<p>Transparent counselling fees for individuals, couples and families in Nigeria and the diaspora.</p>', NULL, 'publish', '2026-08-22 02:44:46.858+00', '2026-08-04 03:53:11.914+00', NULL, NULL, '{"sections": [{"id": "pricing-hero", "body": "Transparent fees for individuals, couples and families in Nigeria and the diaspora. Payments are processed securely.", "type": "hero", "align": "left", "image": {"alt": "", "src": ""}, "links": [{"id": "pricing-hero-book", "href": "/book", "label": "Start secure booking", "variant": "primary"}], "width": "wide", "hidden": false, "eyebrow": "Affordable therapy plans", "heading": "Professional counselling —", "spacing": "lg", "surface": "cream", "headingAfter": ".", "headingEmphasis": "accessible"}, {"id": "pricing-single", "body": "Best for first appointments, focused support, or clients who prefer to book one session at a time.", "type": "cardGrid", "align": "left", "cards": [{"id": "price-clarity", "body": "A short paid call to choose the right service, ask a focused question, or plan your next step.", "href": "/contact", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Clarity Call", "bullets": ["15-minute online or phone call", "Service-fit guidance", "Clear next-step recommendation", "Not a full therapy session"], "tagline": "Contact for pricing · per 15-minute consultation", "linkLabel": "Request a call"}, {"id": "price-individual", "body": "One-to-one online counselling tailored to your current concerns and treatment goals.", "href": "/book?service=individual&mode=online", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Individual Therapy", "bullets": ["Online video session", "CBT-informed support", "Mindfulness and solution-focused tools", "Personalised next steps after session"], "tagline": "₦55,000 · per 60-minute session", "linkLabel": "Start secure booking"}, {"id": "price-couple", "body": "Structured couple therapy for communication, trust repair, conflict and emotional intimacy.", "href": "/book?service=couple&mode=online", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Couple Therapy", "bullets": ["Online video session", "Couple assessment and profiling", "Communication and conflict skills", "Infidelity-sensitive support when needed"], "tagline": "₦90,000 · per 90-minute session", "linkLabel": "Start secure booking"}, {"id": "price-teen", "body": "Specialist support for children and adolescents, with age-appropriate therapeutic methods.", "href": "/contact", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Child/Teen Therapy", "bullets": ["Behavioural and emotional support", "School-related concerns", "Play, art and talk therapy methods", "Parent guidance where appropriate"], "tagline": "₦50,000 · per 60-minute session", "linkLabel": "Request a slot"}], "width": "wide", "hidden": false, "columns": 4, "eyebrow": "Single sessions", "heading": "Pay per session.", "spacing": "md", "surface": "page"}, {"id": "pricing-in-person", "body": "For clients who prefer face-to-face support. In-person sessions are available by appointment.", "type": "cardGrid", "align": "left", "cards": [{"id": "price-in-person-individual", "body": "One-to-one counselling in a private Talk Space room, tailored to your treatment goals.", "href": "/book?service=individual&mode=in_person", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Individual In-person Session", "bullets": ["Physical session by appointment", "Private counselling room", "CBT-informed support", "Personalised next steps after session"], "tagline": "₦85,000 · per 60-minute session", "linkLabel": "Start secure booking"}, {"id": "price-in-person-couple", "body": "Face-to-face couple therapy for communication, trust repair, conflict and intimacy.", "href": "/book?service=couple&mode=in_person", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Couple In-person Session", "bullets": ["Physical couple session", "Couple assessment and profiling", "Communication and conflict skills", "Infidelity-sensitive support when needed"], "tagline": "₦130,000 · per 90-minute session", "linkLabel": "Start secure booking"}, {"id": "price-in-person-month-individual", "body": "Four face-to-face individual therapy sessions with the same therapist.", "href": "/book?service=one_month_individual&mode=in_person", "tone": "default", "image": {"alt": "", "src": ""}, "title": "One-Month Individual In-person", "bullets": ["Four physical sessions", "Consistent therapist match", "Progress tracking between sessions", "Structured short-course care"], "tagline": "₦323,000 · 4 individual sessions monthly", "linkLabel": "Start secure booking"}, {"id": "price-in-person-month-couple", "body": "A structured month of in-person couple therapy for reconnection and repair.", "href": "/book?service=one_month_couple&mode=in_person", "tone": "default", "image": {"alt": "", "src": ""}, "title": "One-Month Couple In-person", "bullets": ["Four physical couple sessions", "Assessment-led treatment plan", "Communication and intimacy work", "Support for recurring conflict cycles"], "tagline": "₦494,000 · 4 couple sessions monthly", "linkLabel": "Start secure booking"}], "width": "wide", "hidden": false, "columns": 4, "eyebrow": "In-person sessions", "heading": "Physical sessions at our rooms.", "spacing": "md", "surface": "cream"}, {"id": "pricing-monthly", "body": "Four-session plans for clients who want rhythm, continuity and a clearer therapeutic arc.", "type": "cardGrid", "align": "left", "cards": [{"id": "price-month-individual", "body": "A focused month of individual therapy with the same therapist and structured follow-up.", "href": "/book?service=one_month_individual&mode=online", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Individual Plan", "bullets": ["Four online sessions", "Consistent therapist match", "Progress tracking between sessions", "Most affordable individual route"], "tagline": "₦210,000 · 4 individual sessions monthly", "linkLabel": "Start secure booking"}, {"id": "price-month-couple", "body": "A structured month of couple therapy for communication, reconnection and repair.", "href": "/book?service=one_month_couple&mode=online", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Couple Plan", "bullets": ["Four online couple sessions", "Assessment-led treatment plan", "Communication and intimacy work", "Support for recurring conflict cycles"], "tagline": "₦342,000 · 4 couple sessions monthly", "linkLabel": "Start secure booking"}, {"id": "price-month-premarital", "body": "Guided sessions for engaged or seriously committed partners preparing for marriage.", "href": "/contact", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Premarital Plan", "bullets": ["Communication and expectations", "Family systems and in-law conversations", "Finance, faith and shared values", "Personalised couple recommendations"], "tagline": "Contact for pricing · structured premarital package", "linkLabel": "Ask for package"}], "width": "wide", "hidden": false, "columns": 3, "eyebrow": "Monthly packages", "heading": "Commit to a short course of care.", "spacing": "md", "surface": "cream"}, {"id": "pricing-specialized", "body": "Specialist support for deeper therapeutic work, relationship repair and workplace wellbeing.", "type": "cardGrid", "align": "left", "cards": [{"id": "price-psychotherapy", "body": "Longer-term therapy for trauma, complex grief and deeper psychological work.", "href": "/contact", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Psychotherapy", "bullets": ["Trauma-informed practice", "Longer therapeutic arc", "Regular clinical review", "Referral support where needed"], "tagline": "Contact for pricing · extended therapeutic work", "linkLabel": "Discuss psychotherapy"}, {"id": "price-infidelity", "body": "Structured support after betrayal, for individuals or couples deciding how to move forward.", "href": "/contact", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Infidelity Recovery", "bullets": ["Stabilise conflict and emotion", "Guided disclosure conversations", "Trust repair or clear decisions", "Individual and joint sessions"], "tagline": "Contact for pricing · structured recovery package", "linkLabel": "Ask about recovery"}, {"id": "price-organizational", "body": "Confidential employee support, wellness sessions and leadership coaching for teams.", "href": "/contact", "tone": "default", "image": {"alt": "", "src": ""}, "title": "Organizational Counselling", "bullets": ["EAP-style staff support", "Team wellness sessions", "Burnout and conflict support", "Reporting on uptake, never on identities"], "tagline": "Contact for pricing · per organisation, scoped to need", "linkLabel": "Request a proposal"}], "width": "wide", "hidden": false, "columns": 3, "eyebrow": "Specialized packages", "heading": "Care for complex or specialist needs.", "spacing": "md", "surface": "page"}, {"id": "pricing-note", "body": "Sliding-scale slots are limited and awarded at our discretion. If cost is a barrier, tell us and we will look at the options with you.", "type": "callout", "align": "left", "width": "content", "hidden": false, "bullets": ["No payment is taken until your appointment is confirmed", "Reschedule free of charge up to 24 hours before your session", "Multi-session plans are refundable pro-rata within 60 days"], "eyebrow": "Good to know", "heading": "Fees are always confirmed before your session.", "spacing": "md", "surface": "deep"}, {"id": "pricing-faq", "body": "", "type": "faq", "align": "left", "items": [{"id": "payment-timing", "answer": "Payments are processed securely via Paystack when you book. If you need to reschedule or cancel, do so at least 48 hours in advance.", "question": "When is payment taken?"}, {"id": "payment-methods", "answer": "Card (Visa, Mastercard, Verve), bank transfer and USSD via Paystack. Corporate invoicing is available for HR-sponsored programmes.", "question": "What payment methods do you accept?"}, {"id": "diaspora-pricing", "answer": "Yes. USD equivalents are shown for each plan and you can pay in either currency via Paystack.", "question": "Do you offer diaspora pricing?"}, {"id": "package-booking", "answer": "Yes. Our one-month plans (four sessions) are the most affordable way to commit to a short course of therapy.", "question": "Can I book a package rather than pay per session?"}], "width": "wide", "hidden": false, "eyebrow": "Billing FAQ", "heading": "Common questions about fees.", "spacing": "lg", "surface": "page"}]}', '2026-08-04 03:53:11.914+00', '2026-08-22 02:44:46.951673+00', NULL, NULL, NULL, NULL),
