	('ad56232f-b8f9-4e99-8616-9cde0e363126', 'faq', '31bd33b9-74c0-4a54-ad90-fd511c263c4b', 'update', '{"id": "31bd33b9-74c0-4a54-ad90-fd511c263c4b", "answer": "You can reschedule up to 48 hours before your session at no charge. Later changes may be billed at 50% of the session fee.", "category": "Fees & access", "question": "What is your cancellation policy?", "created_at": "2026-07-19T20:24:18.268584+00:00", "updated_at": "2026-07-20T06:08:14.01351+00:00", "is_published": true, "display_order": 30}', '8a8d4e3a-30d4-4edb-8550-9cdc5750dc9a', 'admin@talkspace.ng', '2026-07-20 06:08:14.01351+00'),
