	('b10831d5-2c10-4438-a473-4136e1470020', 'content_entry', 'c0156a5f-4eab-4f6d-861f-6c68ece2ea46', 'create', '{"id": "c0156a5f-4eab-4f6d-861f-6c68ece2ea46", "kind": "page", "slug": "about-mse3xzgd", "title": "About", "metadata": {}, "body_html": null, "source_id": 1785814666429, "updated_at": "2026-08-04T03:37:46.55953+00:00", "archived_at": null, "archived_by": null, "author_name": null, "imported_at": "2026-08-04T03:37:46.429+00:00", "excerpt_html": null, "published_at": null, "source_status": "draft", "canonical_path": "/content/pages/about-mse3xzgd", "source_modified_at": "2026-08-04T03:37:46.429+00:00", "featured_media_path": null, "scheduled_publish_at": null}', 'e25f08cf-1572-4965-b9dc-0d9c1458ff32', 'enyaelvis@gmail.com', '2026-08-04 03:37:46.55953+00'),
	('0520a1c1-a243-4ed2-94d1-69dab5f1ae42', 'faq', '2a0093dd-828e-4a38-86b3-f3b13bdafde2', 'create', '{"id": "2a0093dd-828e-4a38-86b3-f3b13bdafde2", "answer": "Individual sessions are 50 minutes. Couples and family sessions are 75 minutes. Group sessions are 90 minutes.", "category": "How sessions work", "question": "How long is a session?", "created_at": "2026-08-05T09:57:39.724485+00:00", "updated_at": "2026-08-05T09:57:39.724485+00:00", "is_published": true, "display_order": 20}', NULL, NULL, '2026-08-18 17:58:43.755057+00'),
