INSERT INTO "public"."email_template_settings" ("template_key", "display_name", "description", "is_enabled", "subject_override", "updated_at") VALUES
	('booking_confirmation', 'Booking confirmation', 'Sent to the client when a session is confirmed.', true, NULL, '2026-07-19 20:24:08.048424+00'),
	('booking_reminder_24h', 'Reminder — 24 hours before', 'Sent to the client 24 hours before their session.', true, NULL, '2026-07-19 20:24:08.048424+00'),
	('booking_reminder_1h', 'Reminder — 1 hour before', 'Sent to the client 1 hour before their session.', true, NULL, '2026-07-19 20:24:08.048424+00'),
	('reschedule_notice', 'Reschedule notice', 'Sent when a session is moved to a new time.', true, NULL, '2026-07-19 20:24:08.048424+00'),
	('cancellation_notice', 'Cancellation notice', 'Sent when a session is cancelled.', true, NULL, '2026-07-19 20:24:08.048424+00'),
	('contact_admin_notice', 'Contact form — admin notice', 'Sent to the care team inbox when a new message arrives.', true, NULL, '2026-07-19 20:24:08.048424+00'),
	('password_reset', 'Password reset', 'Sent when a user requests a password reset.', true, NULL, '2026-07-19 20:24:08.048424+00'),
	('contact_ack', 'Contact form — acknowledgement', 'Sent to the person who filled the contact form.', true, NULL, '2026-07-26 11:27:53.976297+00'),
	('form_reminder', 'Form completion reminder', 'Sent by an administrator when a client has an unfinished booking or contact form.', true, NULL, '2026-08-02 04:02:05.508081+00'),
	('payment_success', 'Payment confirmation', 'Sent when an online payment or bank transfer is confirmed.', true, NULL, '2026-08-02 04:14:25.330008+00'),
	('payment_failed', 'Payment failed', 'Sent when an online payment fails or is abandoned.', true, NULL, '2026-08-02 04:14:25.330008+00'),
	('bank_transfer_received', 'Bank transfer received', 'Sent when a client submits bank-transfer details for review.', true, NULL, '2026-08-02 04:14:25.330008+00'),
	('package_booking_link', 'Package booking link', 'Sent when a client can schedule remaining sessions from a paid package.', true, NULL, '2026-08-18 17:59:24.937231+00');


--
