--

INSERT INTO "public"."faqs" ("id", "category", "question", "answer", "is_published", "display_order", "created_at", "updated_at") VALUES
	('d1b1923a-f088-4754-8ced-adbb76336299', 'Getting started', 'How do I book a first session?', 'Use the Book a session button anywhere on the site, or message us on WhatsApp. You''ll share a few details, and a care coordinator will confirm your therapist and slot within one working day.', true, 10, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('2501e551-5161-4dbb-bdda-6c9a3f46351e', 'Getting started', 'How do I know which therapist is right for me?', 'A care coordinator reviews every request and matches you with a therapist whose training and style suit your needs. You can request a change at any point.', true, 20, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('570ee28b-7ca1-4381-ab02-fc688f1922f4', 'Getting started', 'Can I try a session before committing to a plan?', 'Yes, most clients start with a single session. You are never asked to commit to a plan up front.', true, 30, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('cf16937e-8c58-4241-a5be-976da9742d43', 'How sessions work', 'Do you offer online sessions?', 'Yes. Most therapists offer secure video sessions. You''ll receive a private link once your session is confirmed. In-person sessions are available at our Lagos rooms.', true, 10, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('e6c9936b-45d4-49f0-bfc6-cf57bbc8a210', 'How sessions work', 'Can I message my therapist between sessions?', 'Yes, if you''re on a plan. Messages are for brief between-session support, not real-time crisis contact.', true, 30, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('c293fe8c-6289-4b6c-a523-16a0f03b2725', 'Privacy & confidentiality', 'Is what I share really confidential?', 'Yes. Sessions are private and protected by professional ethics. We only share information with your explicit consent, or where required by law (for example, imminent risk to life).', true, 10, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('6337d86b-1cb4-41c6-83c5-975db9f64160', 'Privacy & confidentiality', 'How is my data protected?', 'We use encrypted video, encrypted storage and role-based access. See our privacy policy for the full detail.', true, 20, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('d52cb07b-7531-4fae-9856-f5539084281f', 'Fees & access', 'What if I can''t afford full session fees?', 'We keep a limited number of sliding-scale slots for students, unemployed clients and low-income households. Mention this in your booking notes.', true, 10, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('32f667ae-34ed-4ee9-9b96-f04569251045', 'Fees & access', 'Do you accept HMOs?', 'We are integrating with several Nigerian HMOs and can invoice for out-of-network reimbursement. Ask and we will send a coverage note.', true, 20, '2026-07-19 20:24:18.268584+00', '2026-07-19 20:24:18.268584+00'),
	('31bd33b9-74c0-4a54-ad90-fd511c263c4b', 'Fees & access', 'What is your cancellation policy?', 'You can reschedule up to 48 hours before your session at no charge. Later changes may be billed at 50% of the session fee.', true, 30, '2026-07-19 20:24:18.268584+00', '2026-07-20 06:08:14.01351+00'),
	('ce89030c-c8d8-41df-ad71-188f9d50bbc6', 'How sessions work', 'How long is a session?', 'Individual sessions are 50 minutes. Couple sessions are 75 minutes. Group and family sessions are 90 minutes.', true, 20, '2026-07-19 20:24:18.268584+00', '2026-07-20 06:10:53.107942+00'),
	('81dc2266-e1e7-45f3-a56b-ebb4cf63a82e', 'Getting started', 'How do I book a first session?', 'Use the Book a session button anywhere on the site, or message us on WhatsApp. You''ll share a few details, and a care coordinator will confirm your therapist and slot within one working day.', true, 10, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('c8ec001c-6438-4727-8c7b-52e55c435003', 'Getting started', 'How do I know which therapist is right for me?', 'A care coordinator reviews every request and matches you with a therapist whose training and style suit your needs. You can request a change at any point.', true, 20, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('e32d53ad-02d0-4ac5-b8a9-20e0bbaac03d', 'Getting started', 'Can I try a session before committing to a plan?', 'Yes, most clients start with a single session. You are never asked to commit to a plan up front.', true, 30, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('9e956895-6f49-435f-9a40-995cee9b24b9', 'How sessions work', 'Do you offer online sessions?', 'Yes. Most therapists offer secure video sessions. You''ll receive a private link once your session is confirmed. In-person sessions are available at our Lagos rooms.', true, 10, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('2a0093dd-828e-4a38-86b3-f3b13bdafde2', 'How sessions work', 'How long is a session?', 'Individual sessions are 50 minutes. Couples and family sessions are 75 minutes. Group sessions are 90 minutes.', true, 20, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('7c7e45c0-1d4d-47be-ade7-b82046e168a2', 'How sessions work', 'Can I message my therapist between sessions?', 'Yes, if you''re on a plan. Messages are for brief between-session support, not real-time crisis contact.', true, 30, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('ff904104-88a2-4c75-b4ce-87d3a118f777', 'Privacy & confidentiality', 'Is what I share really confidential?', 'Yes. Sessions are private and protected by professional ethics. We only share information with your explicit consent, or where required by law (for example, imminent risk to life).', true, 10, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('5da1e80d-0c0f-42bb-965b-e71fb7ea2dc9', 'Privacy & confidentiality', 'How is my data protected?', 'We use encrypted video, encrypted storage and role-based access. See our privacy policy for the full detail.', true, 20, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('7985e1f9-0b90-4ec9-87fa-dd693161c8c2', 'Fees & access', 'What if I can''t afford full session fees?', 'We keep a limited number of sliding-scale slots for students, unemployed clients and low-income households. Mention this in your booking notes.', true, 10, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('56c32f36-a590-42de-93f6-0e996a9884bb', 'Fees & access', 'Do you accept HMOs?', 'We are integrating with several Nigerian HMOs and can invoice for out-of-network reimbursement. Ask and we will send a coverage note.', true, 20, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00'),
	('02609838-9277-4ae1-bd94-c1e0d87c1ef7', 'Fees & access', 'What is your cancellation policy?', 'You can reschedule up to 24 hours before your session at no charge. Later changes may be billed at 50% of the session fee.', true, 30, '2026-08-05 09:57:39.724485+00', '2026-08-05 09:57:39.724485+00');


