INSERT INTO "public"."site_settings" ("key", "value", "updated_at") VALUES
	('site_details', '{"email": "hello@talkspace.ng", "hours": "Mon to Fri · 10:00 am to 5:00 pm WAT", "phone": "+234 809 993 1039", "tagline": "Confidential. Professional. Accessible.", "twitter": "https://twitter.com/talkspace_ng", "youtube": "https://www.youtube.com/@talkspaceng", "facebook": "https://facebook.com/talkspaceng", "linkedin": "https://www.linkedin.com/company/talkspaceng", "logoPath": "https://vwupdobwjlmitsgasdrz.supabase.co/storage/v1/object/sign/content-media/brand/2026/08/7d6561c2-opt1-horizontal-originalblue-on-white-removebg-preview.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNWYzN2NhOS1jOTdiLTQzZDItOGY4Yy1lNWRkZWU4MTE2N2IiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJjb250ZW50LW1lZGlhL2JyYW5kLzIwMjYvMDgvN2Q2NTYxYzItb3B0MS1ob3Jpem9udGFsLW9yaWdpbmFsYmx1ZS1vbi13aGl0ZS1yZW1vdmViZy1wcmV2aWV3LnBuZyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODU4MzU0NTAsImV4cCI6MjEwMTE5NTQ1MH0.piGy_Vo1aVyLogtjoxW0yr9RLnDJSkT23NSnSMLLnDs", "whatsapp": "+234 704 846 9090", "brandName": "Talk Space Counselling Services", "instagram": "https://instagram.com/talkspace_ng", "appearance": {"bodyFont": "sans", "textColor": "#253044", "accentColor": "#c27b67", "buttonStyle": "rounded", "headingFont": "display", "baseFontSize": "md", "sectionSpacing": "comfortable", "backgroundColor": "#fbfaf7"}, "faviconPath": "https://vwupdobwjlmitsgasdrz.supabase.co/storage/v1/object/sign/content-media/brand/2026/08/3d883882-icon-only-originalblue-fixed-removebg-preview.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9jNWYzN2NhOS1jOTdiLTQzZDItOGY4Yy1lNWRkZWU4MTE2N2IiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJjb250ZW50LW1lZGlhL2JyYW5kLzIwMjYvMDgvM2Q4ODM4ODItaWNvbi1vbmx5LW9yaWdpbmFsYmx1ZS1maXhlZC1yZW1vdmViZy1wcmV2aWV3LnBuZyIsInNjb3BlIjoiZG93bmxvYWQiLCJpYXQiOjE3ODU4MzU0MzIsImV4cCI6MjEwMTE5NTQzMn0.j5TNhR0YM4uvlT-ON4PMZqV_HLa5IBbCCZjt3CXUbac", "socialImagePath": "/og-image.jpg"}', '2026-08-04 09:24:31.578079+00'),
	('home_specialties', '[{"alt": "Individual therapy in a calm counselling setting.", "title": "Individual Therapy", "imageUrl": "specialties/2026/08/eaded1d9-749076681-889200533750224-3848560230140989437-n.webp"}, {"alt": "Couples therapy in a peaceful shared space.", "title": "Couples Counselling", "imageUrl": "specialties/2026/08/c4f8787d-749514423-975000655574803-2636807709468012368-n.webp"}, {"alt": "Trauma-informed therapy support.", "title": "Trauma Support", "imageUrl": "specialties/2026/08/0f9e853c-748096561-4424089421253501-9203386933650355873-n.webp"}, {"alt": "A family support conversation in a warm room.", "title": "Family Sessions", "imageUrl": "specialties/2026/08/b2a7b435-749300554-2217117405742463-1405482664151013572-n.webp"}, {"alt": "Psychotherapy support from Talk Space.", "title": "Psychotherapy Assessment", "imageUrl": "specialties/2026/08/33752457-748096592-1654591175614952-4141682586154594891-n.webp"}, {"alt": "Teen therapy support from Talk Space.", "title": "Teen/Child Therapy", "imageUrl": "specialties/2026/08/1cd62402-751805190-2117789945810418-6027284730328230935-n.webp"}, {"alt": "Organizational counselling support from Talk Space.", "title": "Organizational Counselling", "imageUrl": "specialties/2026/08/852ac76a-750814879-1234303622070810-5586296137706130413-n.webp"}]', '2026-08-04 21:12:25.223403+00'),
	('home_hero', '{"eyebrow": "• A SAFE AND CONFIDENTIAL SPACE •", "description": "Private counselling for individuals, couples, and executives who value privacy as much as progress with licenced and experienced therapists. Online and in-person from Abuja to London", "imageOneAlt": "Therapist and client in a calm individual session", "imageTwoAlt": "Excited couple holding hands with a couple therapist", "imageOnePath": "hero/2026/08/8d5fbd2c-749076681-889200533750224-3848560230140989437-n.webp", "imageTwoPath": "hero/2026/08/17feb5db-762944592-1302761069577370-8869253691306150376-n.webp", "headingBefore": "For the hard conversations", "headingEmphasis": "you can''t have anywhere else", "primaryCtaLabel": "Book a session", "secondaryCtaLabel": "How can we support you?"}', '2026-08-04 21:01:25.781634+00'),
	('home_sections', '[{"id": "hero", "visible": true}, {"id": "carousel", "visible": true}, {"id": "trust", "visible": true}, {"id": "specialties", "visible": true}, {"id": "therapists", "visible": true}, {"id": "video", "visible": true}, {"id": "how_it_works", "visible": true}, {"id": "pricing", "visible": true}, {"id": "reviews", "visible": true}, {"id": "journal", "visible": true}, {"id": "faq", "visible": true}, {"id": "cta", "visible": true}]', '2026-08-04 08:41:41.30053+00'),
	('home_section_copy', '{"cta": {"body": "", "title": "It''s time to move from distress to clarity, connection and stability.", "eyebrow": "Take the first step"}, "faq": {"body": "", "title": "Answers to the questions we hear most.", "eyebrow": "FAQ"}, "hero": {"body": "", "title": "", "eyebrow": ""}, "trust": {"body": "", "title": "", "eyebrow": ""}, "video": {"body": "Whether your goal is to deepen your connection, manage conflict or preserve your marriage from infidelity, we use research-based principles for long-lasting, harmonious relationships.", "title": "Making Marriage Work, from the Talk Space channel.", "eyebrow": "Watch"}, "journal": {"body": "", "title": "Reflections from Talk Space therapists.", "eyebrow": "Latest from the journal"}, "pricing": {"body": "", "title": "Professional counselling, effective, confidential and accessible.", "eyebrow": "Affordable therapy plans"}, "reviews": {"body": "", "title": "Stories of healing, stillness, and finding one''s rhythm once more.", "eyebrow": "Testimonials"}, "carousel": {"body": "", "title": "", "eyebrow": ""}, "therapists": {"body": "A team grounded in empathy, training, and cultural understanding.", "title": "Meet the people behind Talk Space", "eyebrow": "Our therapists"}, "specialties": {"body": "Thoughtful, culturally attuned support for the moments and relationships that matter most.", "title": "Where the work begins", "eyebrow": "Our specialties"}, "how_it_works": {"body": "", "title": "From first message to first session, with dignity, at your pace.", "eyebrow": "Meet a therapist in 3 easy steps"}}', '2026-08-10 10:14:07.855103+00'),
	('google_reviews', '{"label": "on Google", "rating": 5, "reviews": [{"date": "6 months ago", "name": "ibrahim oliyide", "quote": "My experience with Tunbi Olabisi''s online counseling service was very positive. The individual therapy sessions helped me manage stress and emotional challenges."}, {"date": "6 months ago", "name": "Inioluwa Opemipo", "quote": "From couple therapy to individual sessions, every interaction felt supportive and professional. Tunbi Olabisi truly cares about her clients."}, {"date": "10 months ago", "name": "Faizah Bukoye", "quote": "Honest review here - if you have been looking for a counselor, look no further. My experience with Talkspace was an amazing one from the first call to my last session. Mrs Tunbi is very thorough, calm, pays attention and helps you navigate seamlessly. I am earnestly grateful she was my counselor."}, {"date": "11 months ago", "name": "Oluwafemi Adeyinka", "quote": "At first I was not sure online counselling would help, but Talkspace proved me wrong. The sessions felt safe, real, and gave me practical steps to manage my emotions better."}, {"date": "7 months ago", "name": "AkIn Oyekan Love", "quote": "Tunbi Olabisi provides a very professional counseling service. I benefited greatly from individual therapy and online counseling sessions. She helped me understand my emotions better and guided me through trauma and anxiety with patience and care."}, {"date": "11 months ago", "name": "Aromokun Tolulope", "quote": "As a Nigerian living in Canada, finding a counsellor who understands both my cultural background and my personal struggles was tough. Talk Space Counselling Services gave me that safe space. The sessions helped me deal with stress, marriage issues, and identity conflicts. Therapy here truly feels like home away from home."}, {"date": "7 months ago", "name": "Loading joe", "quote": "Tunbi Olabisi provides excellent counselling services. She is patient, professional and truly passionate about emotional healing and mental wellness."}, {"date": "11 months ago", "name": "Nkem Jessica", "quote": "Therapy with Talk Space Counseling Services was life changing. From stress at work to personal trauma, my therapist helped me heal step by step. It feels good to finally speak without fear of being judged."}], "reviewUrl": "https://www.google.com/maps/place/Talk+Space+Counselling/@6.6023494,3.3490401,17z/data=!4m14!1m7!3m6!1s0x103b8de64685748f:0x8dc76851d944dcc5!2sTalk+Space+Counselling!8m2!3d6.6023494!4d3.351615!16s%2Fg%2F11thf1nftr!3m5!1s0x103b8de64685748f:0x8dc76851d944dcc5!8m2!3d6.6023494!4d3.351615!16s%2Fg%2F11thf1nftr?entry=ttu", "reviewCount": 51, "lastSyncedAt": "2026-08-22T02:57:12.231Z", "googlePlaceId": "ChIJj3SFRuaNOxARxdxE2VFox40", "lastSyncError": null, "lastSyncSource": "scrape"}', '2026-08-22 02:57:18.135629+00');


